"""Declarative base and the constraint naming convention Alembic relies on."""

from sqlalchemy import MetaData
from sqlalchemy.orm import DeclarativeBase

# Without an explicit convention, autogenerated migrations get unstable
# constraint names and start dropping/recreating constraints between machines.
NAMING_CONVENTION = {
    "ix": "ix_%(table_name)s_%(column_0_name)s",
    "uq": "uq_%(table_name)s_%(column_0_name)s",
    "ck": "ck_%(table_name)s_%(constraint_name)s",
    "fk": "fk_%(table_name)s_%(column_0_name)s_%(referred_table_name)s",
    "pk": "pk_%(table_name)s",
}


class Base(DeclarativeBase):
    metadata = MetaData(naming_convention=NAMING_CONVENTION)
